import {createCallCenter} from './call-center.mjs';
import {createLeasingWorkspace} from './leasing.mjs';
import {prepareCRM} from './prospects.mjs';
import {properties,sources,themes,leads,reviews,defaultState,restoreState,records,metrics,sourceMetrics,sum,ratio,respond,createTask,bookTour,csv,addDays,selectedSources,reportingRange,periodFactor} from './model.mjs';

// UI state is intentionally local to the demo. No resident data or vendor credentials are sent.
const KEY='mf-hub-demo-v1',root=document.getElementById('app'),dialog=document.getElementById('dialog');
let state=defaultState(),storageAvailable=true;
try{state=restoreState(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{storageAvailable=false;}
prepareCRM(state);
const filters={property:'all',pmc:'all',city:'all',month:10};
const marketingDefaults=()=>({channel:'all',source:'all',acquisition:'all',range:'month',dateFrom:'2026-10-01',dateTo:'2026-10-31'});
const marketingFilters=marketingDefaults();
let marketingStage='all';
const reportFilters=()=>route().module==='attribution'?{...filters,channel:marketingFilters.channel,source:marketingFilters.source,acquisition:marketingFilters.acquisition,...(marketingFilters.range==='month'?{}:{dateFrom:marketingFilters.dateFrom,dateTo:marketingFilters.dateTo})}:filters;
const marketingStages=[['all','All enquiries'],['scheduled','Tours scheduled'],['toured','Tours completed'],['applied','Applications'],['leased','Leases signed']];
let inboxStatus='open',inboxRating='all',inboxSearch='',inboxPage=0,leadSearch='',leadSource='all',leadPage=0,mobileOpen=false,toastTimer,lastFocus;
const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const num=n=>new Intl.NumberFormat('en-CA',{maximumFractionDigits:0}).format(n);
const money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(n);
const pct=(n,d,dp=1)=>(ratio(n,d)*100).toFixed(dp)+'%';
const pName=id=>properties.find(p=>p.id===id)?.name||'Portfolio';
const sName=id=>sources.find(s=>s.id===id)?.name||'Unknown';
const period=()=>{const {start,end}=reportingRange(reportFilters()),fmt=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});return `${fmt(start)} – ${fmt(end)}`;};
const monthName=()=>Number(filters.month)===10?'October':'September';
const icons={headset:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h4v8H4a1 1 0 0 1-1-1zM21 12h-4v8h3a1 1 0 0 0 1-1zM18 20c0 2-3 2-6 2',
'phone-off':'m3 3 18 18M10 4H7c-2 0-3 1-3 3 0 7 6 13 13 13 2 0 3-1 3-3v-3l-5-1-2 2M7 4l1 5-2 2',portfolio:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',building:'M4 21V5l8-3v19M12 8l8-3v16M2 21h20M7 7v2M7 12v2M7 17v1M16 9v2M16 14v2',chart:'M4 20V4M4 20h17M8 16v-5M13 16V7M18 16v-8',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z',check:'m5 12 4 4L19 6',tasks:'M9 5H5v16h14V5h-4M9 3h6v4H9zM8 12h8M8 16h5',plug:'M8 3v5M16 3v5M6 8h12v3a6 6 0 0 1-6 6v4M6 8v3a6 6 0 0 0 6 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14m-5-5 5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',play:'m8 5 12 7-12 7Z',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M18 8v6M15 11h6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 12h.01',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 4M4 15l2 4a7 7 0 0 0 12-2',message:'M21 3H3v14h5l4 4v-4h9Z'};
const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.chart}"/></svg>`;
const btn=(label,action,attrs='',style='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${label}</button>`;
const chip=(text,type='')=>`<span class="chip ${type}">${esc(text)}</span>`;
const empty=(title,body,button='')=>`<div class="empty">${icon('search',30)}<h3>${title}</h3><p>${body}</p>${button}</div>`;
const metric=(title,value,detail,symbol='chart')=>`<div class="metric"><div class="metric-title">${title}${icon(symbol)}</div><div class="metric-value">${value}</div><div class="metric-detail">${detail}</div></div>`;
const panel=(title,sub,body,action='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const table=(headers,rows)=>`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th${h.startsWith('#')?' class="numeric"':''}>${h.replace(/^#/,'')}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const td=(v,right=false)=>`<td${right?' class="numeric"':''}>${v}</td>`;
const propertyLink=p=>`<button type="button" class="link" data-action="property" data-id="${p.id}">${p.name}</button><small>${p.code} · ${p.city}</small>`;
const stars=n=>`<span class="stars" aria-label="${n} out of 5 stars">${'★'.repeat(n)}${'☆'.repeat(5-n)}</span>`;
const row=(a,b)=>`<div class="row"><span>${a}</span><strong>${b}</strong></div>`;
const names={'call-center':'Call Center',pipeline:'Lead to Lease',communications:'Communications',prospect:'Prospect 360',portfolio:'Portfolio overview',properties:'Properties',reputation:'Online reputation',attribution:'Marketing Intelligence',actions:'Action centre',connections:'Connections',settings:'Brand settings'};
function route(){const [module,tab]=location.hash.slice(1).split('/');return{module:names[module]?module:'portfolio',tab:tab||'overview'};}
function navigate(path){callCenter.resetPage();mobileOpen=false;closeDialog();if(location.hash.slice(1)===path)render();else location.hash=path;window.scrollTo({top:0});}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200);}
function colors(){const palette={teal:['#087e7b','#e6f3f0'],blue:['#315e9e','#eaf0f8'],purple:['#6b53a0','#f0ecf7']};const [color,soft]=palette[state.accent]||palette.teal;document.documentElement.style.setProperty('--brand',color);document.documentElement.style.setProperty('--soft',soft);}
function heading(title,sub,actions='',eyebrow=''){return `<div class="heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function marketingFilterBar(){
 const select=(key,label,value,options,shared=false)=>`<div class="filter"><label for="marketing-${key}">${label}</label><select id="marketing-${key}" ${shared?'data-filter':'data-marketing'}="${key}">${options.map(([id,name])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(name)}</option>`).join('')}</select></div>`;
 const allowed=selectedSources({...marketingFilters,source:'all'}),range=marketingFilters.range==='month'?String(filters.month):marketingFilters.range;
 return `<section class="marketing-filters" aria-label="Marketing report filters"><div class="filters marketing-filter-grid">
 ${select('pmc','Management company',filters.pmc,[['all','All companies'],...[...new Set(properties.map(p=>p.pmc))].map(x=>[x,x])],true)}
 ${select('city','City',filters.city,[['all','All cities'],...[...new Set(properties.map(p=>p.city))].map(x=>[x,x])],true)}
 ${select('property','Property',filters.property,[['all','All properties'],...properties.map(p=>[p.id,p.name])],true)}
 ${select('range','Date range',range,[['10','October 2026'],['9','September 2026'],['all','All available dates'],['custom','Custom date range']])}
 ${select('channel','Marketing channel',marketingFilters.channel,[['all','All channels'],...[...new Set(sources.map(s=>s.channel))].map(x=>[x,x])])}
 ${select('source','Source / platform',marketingFilters.source,[['all','All sources'],...allowed.map(s=>[s.id,s.name])])}
 ${select('acquisition','Acquisition type',marketingFilters.acquisition,[['all','All acquisition'],['paid','Paid media'],['non-paid','Organic / direct / referral'],['unknown','Unknown']])}
 <div class="marketing-filter-actions">${btn(icon('refresh',14)+' Reset','marketing-reset','','secondary')}${btn(icon('download',14)+' Export CSV','export','','secondary')}</div></div>
 ${marketingFilters.range==='custom'?`<form id="marketing-dates" class="marketing-dates"><div class="filter"><label for="marketing-from">Start date</label><input id="marketing-from" name="dateFrom" type="date" required value="${marketingFilters.dateFrom}"></div><div class="filter"><label for="marketing-to">End date</label><input id="marketing-to" name="dateTo" type="date" required value="${marketingFilters.dateTo}"></div><button class="btn" type="submit">Apply dates</button><p class="date-error" id="marketing-date-error" role="alert"></p></form>`:''}
 <div class="marketing-selection" role="status"><strong>${period()}</strong><span>${marketingFilters.channel==='all'?'All channels':esc(marketingFilters.channel)} · ${marketingFilters.source==='all'?'All sources':esc(sName(marketingFilters.source))} · ${marketingFilters.acquisition==='all'?'All acquisition':marketingFilters.acquisition==='paid'?'Paid media':marketingFilters.acquisition==='non-paid'?'Organic / direct / referral':'Unknown'}</span></div>
 <p class="filter-note">Filters apply to Marketing Intelligence and its exports. Sample data: Sep–Oct 2026. Dates select the enquiry creation cohort; outcomes are tracked through Nov 13.${marketingFilters.range==='custom'?' Partial-month spend is estimated from monthly totals using calendar days.':''}</p></section>`;
}
function resetMarketingFilters(){Object.assign(filters,{property:'all',pmc:'all',city:'all',month:10});Object.assign(marketingFilters,marketingDefaults());leadSource='all';leadSearch='';marketingStage='all';leadPage=0;}
function marketingJourneyRecords(m){return m.leads.filter(l=>(leadSource==='all'||l.source===leadSource)&&(marketingStage==='all'||l[marketingStage])&&(!leadSearch||`${l.name} ${pName(l.property)} ${l.id}`.toLowerCase().includes(leadSearch.toLowerCase())));}
function filterBar(){if(route().module==='attribution')return marketingFilterBar();return `<div class="filters">${[['pmc','Management company',['all',...new Set(properties.map(p=>p.pmc))]],['city','City',['all',...new Set(properties.map(p=>p.city))]]].map(([id,label,opts])=>`<div class="filter"><label for="filter-${id}">${label}</label><select id="filter-${id}" data-filter="${id}">${opts.map(v=>`<option value="${v}" ${filters[id]===v?'selected':''}>${v==='all'?'All '+(id==='pmc'?'companies':'cities'):v}</option>`).join('')}</select></div>`).join('')}<div class="filter property"><label for="filter-property">Property</label><select id="filter-property" data-filter="property"><option value="all">All properties</option>${properties.map(p=>`<option value="${p.id}" ${filters.property===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="filter period"><label for="filter-month">Reporting cohort</label><select id="filter-month" data-filter="month"><option value="10" ${Number(filters.month)===10?'selected':''}>October 2026</option><option value="9" ${Number(filters.month)===9?'selected':''}>September 2026</option></select></div>${btn(icon('download')+' Export CSV','export','','secondary')}</div>`;}
function tabs(module,current){const items=module==='reputation'?[['overview','Overview'],['inbox','Review inbox'],['performance','Performance'],['sentiment','Sentiment'],['listings','Listings'],['competitors','Competitors'],['surveys','Surveys']]:[['overview','Overview'],['sources','Sources & spend'],['funnel','Conversion'],['website','Website & paid'],['organic','Organic content'],['journeys','Lead journeys'],['recommendations','Recommendations']];return `<nav class="tabs" aria-label="${module} views">${items.map(([id,label])=>`<button type="button" class="tab ${current===id?'active':''}" data-action="navigate" data-route="${module}/${id}" ${current===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;}
function funnel(m){const keys=['all','scheduled','toured','applied','leased'];return [['Enquiries',m.leads.length],['Tours scheduled',m.scheduled],['Tours completed',m.toured],['Applications',m.applied],['Leases signed',m.leases]].map(([label,value],i)=>`<button type="button" class="funnel-row funnel-button" data-action="${route().module==='attribution'?'marketing-stage':'drill-stage'}" data-stage="${keys[i]}" aria-label="View ${value} ${label.toLowerCase()}"><span>${label}</span><span class="bar-track"><span class="bar" style="width:${ratio(value,m.leads.length)*100}%"></span></span><span class="bar-value">${value} →</span></button>`).join('')+'<div class="footnote">Same creation cohort · outcomes through Nov 13, 2026.</div>';}
function sourceBars(data,key='leases'){const max=Math.max(1,...data.map(s=>s[key]));return data.map(s=>`<div class="funnel-row" style="grid-template-columns:116px 1fr 32px"><span>${s.name}</span><div class="bar-track" style="height:18px"><div class="bar" style="background:${s.color};width:${s[key]/max*100}%"></div></div><span class="bar-value">${s[key]}</span></div>`).join('');}
function lineChart(values,labels,max=5,description='Weekly rating'){const x=i=>40+i*540/Math.max(1,values.length-1),y=v=>158-125*v/max,points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<svg class="chart" viewBox="0 0 600 195" role="img" aria-label="${esc(description)}: ${values.map((v,i)=>labels[i]+' '+v.toFixed(1)).join(', ')}">${(max===5?[0,.2,.4,.6,.8,1]:[0,.25,.5,.75,1]).map(n=>`<line class="axis" x1="40" y1="${y(max*n)}" x2="580" y2="${y(max*n)}"/><text x="0" y="${y(max*n)+4}">${max<=5?(max*n).toFixed(1):num(max*n)}</text>`).join('')}<polygon points="40,158 ${points} 580,158" fill="var(--brand)" opacity=".055"/><polyline class="line" points="${points}"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="var(--brand)"/><text x="${x(i)}" y="185" text-anchor="${i===0?'start':i===values.length-1?'end':'middle'}">${labels[i]}</text>`).join('')}</svg>`;}
function propertyTable(m,kind='portfolio'){return table(kind==='reputation'?['Property','#Reviews','#Rating','#Response rate','#Open','Owner']:['Property','#Occupancy','#Enquiries','#Leases','#Ad spend / lease','Review queue'],m.properties.map(p=>{const a=metrics({...filters,property:p.id},state);return `<tr>${td(propertyLink(p))}${kind==='reputation'?td(a.reviews.length,true)+td(a.rating.toFixed(2)+' / 5',true)+td(pct(a.answered,a.reviews.length),true)+td(chip(a.open+' open',a.open>5?'warn':'good'),true)+td(p.owner):td(pct(p.occupied,p.homes),true)+td(btn(a.leads.length,'drill-stage',`data-stage="all" data-property="${p.id}"`,'ghost'),true)+td(btn(a.leases,'drill-stage',`data-stage="leased" data-property="${p.id}"`,'ghost'),true)+td(a.leases?money(a.spend/a.leases):'—',true)+td(chip(a.overdue>0?'Needs response':'Within target',a.overdue>0?'warn':'good'))}</tr>`;}));}
function render(){colors();const {module,tab}=route(),m=metrics(reportFilters(),state);document.title=names[module]+' · MF Hub';const nav=[['portfolio','portfolio'],['properties','building'],['pipeline','people'],['communications','message'],['call-center','headset'],['attribution','chart'],['reputation','star'],['actions','tasks']];root.innerHTML=`<aside class="sidebar ${mobileOpen?'open':''}" aria-label="Main navigation"><div class="wordmark">${icon('building',27)}MF Hub</div><div class="brand-sub">${esc(state.brand)}</div><div class="nav-label">Workspace</div>${nav.map(([id,symbol])=>`<button type="button" class="nav ${module===id?'active':''}" data-action="navigate" data-route="${id}" ${module===id?'aria-current="page"':''}>${icon(symbol)}${names[id]}${id==='actions'&&state.tasks.some(t=>t.status!=='Done')?`<span class="count">${state.tasks.filter(t=>t.status!=='Done').length}</span>`:''}</button>`).join('')}<div class="nav-label">Platform</div>${[['connections','plug'],['settings','settings']].map(([id,symbol])=>`<button type="button" class="nav ${module===id?'active':''}" data-action="navigate" data-route="${id}">${icon(symbol)}${names[id]}</button>`).join('')}<div class="sidebar-bottom"><div class="workspace-status">Private demo workspace</div><div>4 properties · 1,000 homes</div><div style="margin-top:13px;color:#7890a8">Marketing. Leasing. Connected.</div></div></aside>${mobileOpen?'<button class="mobile-scrim" data-action="close-menu" aria-label="Close navigation"></button>':''}<div class="layout"><header class="topbar"><button type="button" class="menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="${mobileOpen}">${icon('menu',22)}</button><div class="topbar-brand"><div class="crumb">Workspace / ${names[module]}</div><div class="workspace-name">${esc(state.brand)}</div></div><div class="top-actions"><button type="button" class="search" data-action="search" aria-label="Search portfolio">${icon('search',15)}<span>Search your portfolio</span><kbd>⌘K</kbd></button><span class="badge">Sample data</span><span class="avatar teal">AK</span></div></header><main id="main" class="main" tabindex="-1">${!['actions','connections','settings','prospect'].includes(module)?filterBar():''}${['actions','connections','settings','prospect'].includes(module)||m.properties.length?view(module,tab,m):heading(names[module],'Adjust your filters to see matching properties.')+panel('No properties match','',empty('No matching properties','The selected property, city and company do not overlap.',btn('Clear filters','clear')))}<footer class="footer"><span>Fictional portfolio & records · ${storageAvailable?'Demo actions saved in this browser':'Demo actions available for this session'} · No live vendor connections · Communications are simulated</span><button type="button" data-action="definitions">Metric definitions ${icon('info',12)}</button></footer></main></div>`;}
function view(module,tab,m){if(module==='call-center')return callCenter.dashboard(tab);if(module==='pipeline')return leasing.list(tab);if(module==='communications')return leasing.list('all',true);if(module==='prospect')return leasing.detail(tab);if(module==='portfolio')return portfolio(m);if(module==='properties')return propertyDirectory(m);if(module==='reputation')return reputation(tab,m);if(module==='attribution')return attribution(tab,m);if(module==='actions')return actionsView();if(module==='connections')return connectionsView();return settingsView();}

// Portfolio and cross-module drill-downs.
function portfolio(m){return heading('One portfolio. A clearer picture.','Your marketing, leasing and resident experience — in one place.',btn(icon('play',14)+' Guided demo','demo','','secondary'),'Portfolio intelligence')+leasing.stageCards(m)+`<div class="metrics">${metric('Portfolio occupancy',pct(m.occupied,m.homes),`${num(m.occupied)} occupied / ${num(m.homes)} homes`,'building')}${metric('Leases signed',m.leases,`${monthName()} enquiry cohort`,'check')}${metric('Lead-to-lease',pct(m.leases,m.leads.length),`${m.leases} leases from ${m.leads.length} enquiries`,'target')}${metric('Ad spend / lease',m.leases?money(m.spend/m.leases):'—',`${money(m.spend)} advertising spend · CAD`,'chart')}</div>${callCenter.summary()}<div class="grid">${panel('From enquiry to signed lease','Find the points where prospects need attention.',funnel(m),chip('Creation cohort','info'))}${panel('Your next best actions','A focused view of what needs attention.',`<div class="attention"><div class="eyebrow">Resident experience</div><h3>${m.overdue} reviews need a timely response</h3><p>${m.open} reviews are open across the selected properties. Close the loop with residents and give your teams a clear owner.</p>${btn('Open review inbox '+icon('arrow',14),'navigate','data-route="reputation/inbox"','ghost')}</div><div class="row"><div><strong>See which sources deliver leases</strong><small>Compare paid acquisition and original-source credit.</small></div>${btn(icon('arrow'),'navigate','data-route="attribution/sources" aria-label="Compare lead sources"','secondary small')}</div><div class="row"><div><strong>Bring an action to the team</strong><small>${state.tasks.filter(t=>t.status!=='Done').length} open demo tasks</small></div>${btn(icon('arrow'),'navigate','data-route="actions" aria-label="Open action centre"','secondary small')}</div>`)}</div>${panel('Property performance','Compare outcomes before changing your marketing allocation.',propertyTable(m),btn('View properties '+icon('arrow',13),'navigate','data-route="properties"','ghost'),'full')}<div class="grid equal">${panel('Where your leases come from','Original source recorded when the enquiry was created.',sourceBars(sourceMetrics(filters,state)),btn('View marketing intelligence','navigate','data-route="attribution"','ghost'))}${panel('Resident reputation','A shared view of trust across your portfolio.',`<div class="donut-row"><div class="ring" style="--value:${ratio(m.answered,m.reviews.length)*100}"><div class="ring-inner">${pct(m.answered,m.reviews.length,0)}<small>responded</small></div></div><div>${row('Average rating',m.rating.toFixed(2)+' / 5')}${row('Reviews this period',m.reviews.length)}${row('Awaiting response',`<span class="warning">${m.open}</span>`)}</div></div>`,btn('View reputation','navigate','data-route="reputation"','ghost'))}</div>`;}
function propertyDirectory(m){return heading('Every property, in focus.','Open a property to inspect its marketing and resident experience.')+`<div class="grid equal">${m.properties.map(p=>{const a=metrics({...filters,property:p.id},state);return `<section class="panel property-card"><div class="property-head"><div class="building-icon">${icon('building',28)}</div><div><h3>${p.name}</h3><small>${p.city} · ${p.type} · ${p.code}</small></div></div>${row('Management company',p.pmc)}${row('Occupancy',pct(p.occupied,p.homes))}${row('Leases / enquiries',a.leases+' / '+a.leads.length)}${row('Review rating',a.rating.toFixed(2)+' / 5')}${btn('Open property '+icon('arrow',14),'property',`data-id="${p.id}"`,'secondary')}</section>`;}).join('')}</div>`;}

// Birdeye-inspired report hierarchy, using original MF Hub components.
function reputation(tab,m){const titles={overview:'Online reputation at a glance',inbox:'Every review deserves a response',performance:'Property & team performance',sentiment:'Listen to what residents are saying',listings:'Keep every property easy to find',competitors:'See your place in the neighbourhood',surveys:'Turn resident feedback into action'};if(!titles[tab])tab='overview';let body='';
 if(tab==='overview'){
  const trend=[0,1,2,3].map(i=>{const rr=m.reviews.filter(r=>Math.min(3,Math.floor((Number(r.date.slice(-2))-1)/7))===i);return ratio(sum(rr,'rating'),rr.length);});
  body=`<div class="metrics">${metric('Rating this period',m.rating.toFixed(2)+' / 5','Weighted across reviews received','star')}${metric('New reviews',m.reviews.length,`Across ${m.properties.length} properties`,'message')}${metric('Response rate',pct(m.answered,m.reviews.length),`${m.answered} of ${m.reviews.length} reviews answered`,'check')}${metric('Awaiting response',m.open,`<span class="warning">${m.overdue} marked over 48 hours</span>`,'clock')}</div><div class="grid">${panel('Review rating by week','Average of reviews received in each week.',lineChart(trend,['First quarter','Second quarter','Third quarter','Final quarter']))}${panel('Response priorities','Open the queue to assign and respond to a review.',m.properties.map(p=>{const a=metrics({...filters,property:p.id},state);return `<div class="row"><div><strong>${p.name}</strong><small>${a.overdue} overdue · ${p.owner}</small></div>${chip(a.open+' open',a.open>5?'warn':'good')}</div>`;}).join('')+btn('Open response queue '+icon('arrow',14),'navigate','data-route="reputation/inbox"'))}</div>${panel('Property comparison','Ratings and responses for reviews received in the selected period.',propertyTable(m,'reputation'),'','full')}`;
 }else if(tab==='inbox')body=reviewInbox(m);
 else if(tab==='performance'){body=`<div class="metrics">${metric('Responses completed',m.answered,pct(m.answered,m.reviews.length)+' of reviews','check')}${metric('Open reviews',m.open,'Assigned to property teams','message')}${metric('Overdue reviews',m.overdue,'Unanswered · over 48 hours','clock')}${metric('Average rating',m.rating.toFixed(2),'For the selected review period','star')}</div>${panel('Property scorecard','Drill into a property to investigate its response queue.',propertyTable(m,'reputation'),'','full')}${panel('Response ownership','Reassign any open review in the review workspace.',table(['Team member','#Assigned reviews','#Open','#Responded'],properties.map(p=>{const rs=m.reviews.filter(r=>r.owner===p.owner);return `<tr>${td(p.owner)}${td(rs.length,true)}${td(rs.filter(r=>!r.answered).length,true)}${td(rs.filter(r=>r.answered).length,true)}</tr>`;})))}`;}
 else if(tab==='sentiment'){
  const positive=m.reviews.filter(r=>r.rating>=4).length,negative=m.reviews.filter(r=>r.rating<=2).length;
  body=`<div class="metrics">${metric('Positive reviews',pct(positive,m.reviews.length),`${positive} reviews rated 4–5 stars`,'star')}${metric('Neutral reviews',m.reviews.filter(r=>r.rating===3).length,'3-star reviews','message')}${metric('Negative reviews',negative,'1–2-star reviews','message')}${metric('Topics tracked',5,'Illustrative topic assignments','target')}</div><div class="grid equal">${panel('Resident themes','Demo classification: star rating + assigned topic.',themes.map(topic=>{const rs=m.reviews.filter(r=>r.topic===topic),pos=rs.filter(r=>r.rating>=4).length,neutral=rs.filter(r=>r.rating===3).length,neg=rs.filter(r=>r.rating<=2).length;return `<div class="theme"><span>${topic}</span><div class="theme-track" role="img" aria-label="${topic}: ${pos} positive, ${neutral} neutral, ${neg} negative"><span style="width:${ratio(pos,rs.length)*100}%;background:var(--brand)"></span><span style="width:${ratio(neutral,rs.length)*100}%;background:#c8d3d9"></span><span style="width:${ratio(neg,rs.length)*100}%;background:#d4a671"></span></div><strong class="numeric">${rs.length}</strong></div>`;}).join('')+'<div class="legend"><span>Positive</span><span style="--lc:#c8d3d9">Neutral</span><span style="--lc:#d4a671">Negative</span></div>')}${panel('Feedback worth a closer look','Fictional resident comments.',m.reviews.filter(r=>r.rating<=2).slice(0,2).map(r=>`<blockquote class="quote">“${r.text}”<small>${pName(r.property)} · ${r.topic}</small></blockquote>`).join('')+btn('Review resident feedback','navigate','data-route="reputation/inbox"','secondary'))}</div>`;
 }else if(tab==='listings'){
  const issues=m.properties.filter(p=>['north','willow'].includes(p.id)&&!state.listingFixes.includes(p.id));
  body=`<div class="metrics">${metric('Directory records',m.properties.length*12,'12 sample directories per property','globe')}${metric('In sync',m.properties.length*12-issues.length,'Sample listing health','check')}${metric('Needs attention',issues.length,'Hours or phone discrepancy','info')}${metric('Google visibility',num(sum(m.properties,'impressions')*2/3),'Illustrative monthly impressions','search')}</div>${panel('Listing health','Correct a sample listing issue and watch the status update.',table(['Property','Directory','Issue','Status','Action'],m.properties.map(p=>{const has=issues.some(i=>i.id===p.id);return `<tr>${td(propertyLink(p))}${td('Google Business Profile')}${td(has?(p.id==='north'?'Office hours mismatch':'Phone number mismatch'):'Property details aligned')}${td(chip(has?'Needs attention':'In sync',has?'warn':'good'))}${td(has?btn('Review & resolve','listing',`data-id="${p.id}"`,'secondary small'):'—')}</tr>`;})),'','full')}`;
 }else if(tab==='competitors'){
  body=`<div class="insight">${icon('info')}<span>Neighbourhood comparisons use fictional competitors and illustrative lifetime ratings. These are separate from the period-specific ratings in your review reports.</span></div>${panel('Local reputation benchmark','A starting point for a property-level competitive review.',table(['Your property','#Lifetime rating','Nearby community','#Rating','Action'],m.properties.map(p=>{const i=properties.indexOf(p);return `<tr>${td(propertyLink(p))}${td([4.1,4.6,4.3,4.2][i].toFixed(1),true)}${td(['Parkside Commons','Oak Terrace','Maple House','Brookfield Homes'][i])}${td([4.4,4.3,4.5,4.4][i].toFixed(1),true)}${td(btn('Create task','task',`data-key="benchmark-${p.id}" data-property="${p.id}" data-title="Review local reputation benchmark for ${p.name}"`,'secondary small'))}</tr>`;})))}`;
 }else{
  const invites=m.properties.length*300,responses=m.properties.length*60,prom=sum(m.properties,p=>p.survey[0]),det=sum(m.properties,p=>p.survey[2]),nps=Math.round(ratio(prom-det,responses)*100);
  body=`<div class="metrics">${metric('Survey invitations',num(invites),'Illustrative resident survey cohort','message')}${metric('Responses',responses,pct(responses,invites)+' response rate','check')}${metric('Resident NPS',(nps>0?'+':'')+nps,'Promoters minus detractors','people')}${metric('Detractors',det,'Respondents scoring 0–6','info')}</div>${panel('Resident survey scorecard','NPS comes from a separate sample survey, not review stars.',table(['Property','#Invited','#Responses','#Promoters','#Detractors','#NPS'],m.properties.map(p=>`<tr>${td(propertyLink(p))}${td(300,true)}${td(60,true)}${td(p.survey[0],true)}${td(p.survey[2],true)}${td(Math.round((p.survey[0]-p.survey[2])/60*100),true)}</tr>`)),'','full')}${panel('Close the feedback loop','Bring low survey scores into a team follow-up workflow.',`<p class="muted" style="font-size:12px;margin-bottom:17px">Create a sample task to review resident concerns and agree on next steps with the property team.</p>${btn('Create survey follow-up task','task',`data-key="survey-${filters.property}" data-property="${filters.property}" data-title="Review resident survey detractors and agree follow-up owners"`)}`)}`;
 }
 return heading(titles[tab],'Resident experience, made visible. · '+period())+tabs('reputation',tab)+body;
}
function reviewInbox(m){const rs=m.reviews.filter(r=>(inboxStatus==='all'||(inboxStatus==='open'?!r.answered:inboxStatus==='overdue'?!r.answered&&r.overdue:r.answered))&&(inboxRating==='all'||(inboxRating==='negative'?r.rating<=2:r.rating>=4))&&(!inboxSearch||`${r.text} ${r.name} ${pName(r.property)} ${r.topic}`.toLowerCase().includes(inboxSearch.toLowerCase())));inboxPage=Math.min(inboxPage,Math.max(0,Math.ceil(rs.length/6)-1));const page=rs.slice(inboxPage*6,inboxPage*6+6);
 const controls=`<div class="toolbar"><div class="toolbar-group"><select id="inbox-status" aria-label="Review status">${[['open','Awaiting response'],['overdue','Overdue'],['answered','Responded'],['all','All reviews']].map(([v,l])=>`<option value="${v}" ${v===inboxStatus?'selected':''}>${l}</option>`).join('')}</select><select id="inbox-rating" aria-label="Review rating">${[['all','All ratings'],['negative','1–2 stars'],['positive','4–5 stars']].map(([v,l])=>`<option value="${v}" ${v===inboxRating?'selected':''}>${l}</option>`).join('')}</select><small>${rs.length} reviews</small></div><input id="review-search" aria-label="Search reviews" placeholder="Search reviews or topics…" value="${esc(inboxSearch)}"></div>`;
 const list=page.map(r=>`<article class="review"><div><div class="review-person"><span class="avatar">${r.name[0]}</span><div><strong>${r.name}</strong> <small>· ${r.platform}</small><div>${stars(r.rating)}</div></div></div><p>${r.text}</p><div class="review-meta"><strong>${pName(r.property)}</strong><span>· ${r.date}</span>${chip(r.topic)}<span>Owner: ${esc(r.owner)}</span></div></div><div class="review-actions">${chip(r.answered?'Responded':r.overdue?'Overdue':'Awaiting response',r.answered?'good':r.overdue?'warn':'info')}${btn(r.answered?'View response':'Open review','review',`data-id="${r.id}"`,'secondary small')}</div></article>`).join('');
 return panel('Review workspace','Manage responses and ownership across the selected properties.',controls+(list||empty('You’re all caught up','No reviews match these filters.'))+pagination('review',inboxPage,6,rs.length),'','full');}
function pagination(kind,page,size,total){return `<div class="pagination"><span>${total?page*size+1:0}–${Math.min(total,page*size+size)} of ${total}</span><div>${btn('Previous',kind+'-page',`data-delta="-1" ${page===0?'disabled':''}`,'secondary small')}${btn('Next',kind+'-page',`data-delta="1" ${(page+1)*size>=total?'disabled':''}`,'secondary small')}</div></div>`;}

// Halo / Hyly-inspired source and cohort reporting.
function attribution(tab,m){const titles={overview:'Follow the investment. See the impact.',sources:'Which sources earn the next dollar?',funnel:'Find the friction in your leasing funnel',website:'From website visits to enquiries',organic:'Build the audience that builds demand',journeys:'Every lead has a story',recommendations:'Turn performance into a next step'};if(!titles[tab])tab='overview';const scope=reportFilters(),src=sourceMetrics(scope,state);let body='';
 const kpis=`<div class="metrics">${metric('Advertising spend',money(m.spend),marketingFilters.range==='custom'?'Daily prorated estimate for selected dates':'Selected sources and reporting period','chart')}${metric('Unique enquiries',m.leads.length,`${m.paidLeads} from paid sources`,'people')}${metric('Leases signed',m.leases,`${pct(m.leases,m.leads.length)} lead-to-lease conversion`,'check')}${metric('Paid cost / lease',m.paidLeases?money(m.spend/m.paidLeases):'—',`${m.paidLeases} leases from paid sources`,'target')}</div>`;
 if(tab==='overview')body=kpis+`<div class="insight">${icon('spark')}<span><strong>Make the next budget conversation about outcomes.</strong> Compare the cost and conversion of each source, then open the prospect journey behind a lease.</span>${btn('Compare sources '+icon('arrow',14),'navigate','data-route="attribution/sources"','ghost')}</div><div class="grid">${panel('Acquisition to occupancy','Cumulative milestones for the same enquiry cohort.',funnel(m))}${panel('Leases by original source','One original source receives credit for each lease.',sourceBars(src))}</div>${panel('Channel performance','Paid media costs are separated from channels without an allocated cost.',sourceTable(src,true),btn('Full source report','navigate','data-route="attribution/sources"','ghost'),'full')}`;
 else if(tab==='sources')body=kpis+panel('Source efficiency','Select a source to see its enquiry-to-lease records.',sourceTable(src,false),'','full')+`<div class="grid equal">${panel('Where investment goes','Paid advertising only.',src.filter(s=>s.paid).map(s=>row(`<i class="dot" style="background:${s.color}"></i>${s.name}`,money(s.spend)+` <small>(${pct(s.spend,m.spend,0)})</small>`)).join(''))}${panel('Read the costs correctly','A common denominator for each decision.',row('Paid cost per enquiry',m.paidLeads?money(m.spend/m.paidLeads):'—')+row('Paid cost per lease',m.paidLeases?money(m.spend/m.paidLeases):'—')+row('Blended ad spend per lease',m.leases?money(m.spend/m.leases):'—')+'<p class="footnote">Organic/referral costs are unallocated, not zero. These measures cover advertising, not total acquisition cost.</p>')}</div>`;
 else if(tab==='funnel')body=`<div class="metrics">${metric('Lead → scheduled tour',pct(m.scheduled,m.leads.length),`${m.scheduled} of ${m.leads.length} enquiries`,'people')}${metric('Tour → application',pct(m.applied,m.toured),`${m.applied} of ${m.toured} completed tours`,'check')}${metric('Application → lease',pct(m.leases,m.applied),`${m.leases} of ${m.applied} applicants`,'target')}${metric('P75 time to lease',m.p75===null?'—':m.p75+' days','Converted leads · nearest-rank percentile','clock')}</div><div class="grid equal">${panel('The conversion funnel','Track the full journey using one cohort.',funnel(m))}${panel('Conversion by property','Click a property to investigate its marketing mix.',table(['Property','#Leads','#Leases','#Lead-to-lease'],m.properties.map(p=>{const a=metrics({...scope,property:p.id},state);return `<tr>${td(propertyLink(p))}${td(a.leads.length,true)}${td(a.leases,true)}${td(pct(a.leases,a.leads.length),true)}</tr>`;})))}</div>${panel('Leasing velocity','Elapsed days from enquiry creation to signed lease, among converted records.',table(['Prospect','Property','Original source','#Days to lease'],m.leads.filter(l=>l.leased).slice(0,8).map(l=>`<tr>${td(`<button type="button" class="link" data-action="lead" data-id="${l.id}">${l.name}</button>`)}${td(pName(l.property))}${td(sName(l.source))}${td(l.days,true)}</tr>`)),btn('All lead journeys','navigate','data-route="attribution/journeys"','ghost'),'full')}`;
 else if(tab==='website'){
  const f=periodFactor(scope),sessions=Math.round(sum(m.properties,'sessions')*f),users=Math.round(sum(m.properties,'users')*f),engaged=Math.round(sum(m.properties,'engaged')*f),impressions=Math.round(sum(m.properties,'impressions')*f),clicks=Math.round(sum(m.properties,'clicks')*f),g=src.find(s=>s.id==='google')||{spend:0,leads:0,leases:0};
  body=`<div class="metrics">${metric('Website sessions',num(sessions),'Illustrative web analytics period','globe')}${metric('Website users',num(users),'Distinct users within the sample period','people')}${metric('Engagement rate',pct(engaged,sessions),`${num(engaged)} engaged sessions`,'chart')}${metric('Google Ads CTR',pct(clicks,impressions),`${num(clicks)} clicks / ${num(impressions)} impressions`,'target')}</div><div class="grid equal">${panel('Website traffic','Illustrative distribution across four equal parts of the selected period.',lineChart([.21,.26,.24,.29].map(n=>sessions*n),['1–7','8–14','15–21','22–end'],Math.max(1,Math.ceil(sessions*.3/1000)*1000),'Website sessions by period segment'))}${panel('Paid search efficiency','Advertising activity and attributed enquiries.',row('Google Ads spend',money(g.spend))+row('Average cost per click',clicks?'CA$'+(g.spend/clicks).toFixed(2):'—')+row('Attributed enquiries',g.leads)+row('Click → enquiry',pct(g.leads,clicks))+row('Original-source leases',g.leases)+'<p class="footnote">Web sessions, users and clicks have different counting rules. Web analytics are illustrative; enquiries and leases come from sample prospect records.</p>')}</div>${panel('Website performance by property','A separate analytical view from the enquiry cohort.',table(['Property','#Sessions','#Users','#Engaged sessions'],m.properties.map(p=>`<tr>${td(propertyLink(p))}${td(num(Math.round(p.sessions*f)),true)}${td(num(Math.round(p.users*f)),true)}${td(num(Math.round(p.engaged*f)),true)}</tr>`)),'','full')}`;
 }else if(tab==='organic'){
  const n=m.properties.length,f=periodFactor(scope,.9);
  body=`<div class="metrics">${metric('Content reach',num(Math.round(n*12000*f)),'Illustrative organic social reach','people')}${metric('Engagements',num(Math.round(n*690*f)),'Likes, comments, shares and saves','message')}${metric('Profile visits',num(Math.round(n*380*f)),'Sample social profile activity','globe')}${metric('Organic search leads',src.find(s=>s.id==='organic')?.leads||0,'Original source · separate from social','search')}</div>${panel('Content that starts a conversation','Selected fictional content examples; not the complete period total.',table(['Content','Format','Objective','#Reach','#Engagements'],[['A day in the neighbourhood','Short video','Discovery',8200,492],['Meet your property team','Carousel','Trust',6100,427],['Inside a two-bedroom home','Walkthrough','Consideration',9400,564],['Residents’ weekend guide','Carousel','Community',4300,301]].map(([name,format,goal,reach,eng])=>`<tr>${td(`<strong>${name}</strong>`)}${td(format)}${td(goal)}${td(num(Math.round(reach*n/4*f)),true)}${td(num(Math.round(eng*n/4*f)),true)}</tr>`)),'','full')}<div class="insight">${icon('info')}<span>Content engagement helps explain audience interest. This demo does not assign leases to a post without a matched prospect journey.</span></div>`;
 }else if(tab==='journeys')body=leadJourneys(m);
 else body=recommendations(m,src);
 return heading(tab==='overview'?'Marketing Intelligence':titles[tab],`Original-source attribution · ${period()} · Outcomes through Nov 13, 2026`,'',tab==='overview'?'': 'Marketing Intelligence')+tabs('attribution',tab)+(['website','organic'].includes(tab)?`<div class="insight">${icon('info')}<span>Traffic and content examples cover the selected properties and dates; source and channel breakdowns are unavailable for those aggregates. Channel, source and acquisition filters apply to prospect counts and attributed media spend. Partial periods use prorated sample totals.</span></div>`:'')+(!m.leads.length?empty('No enquiries match these filters','Try another channel, source or date range.',btn('Reset marketing filters','marketing-reset','','secondary')):'')+body;
}
function sourceTable(src,compact){return table(compact?['Source','#Enquiries','#Leases','#Spend','#Cost / lease']:['Original source','#Enquiries','#Scheduled','#Toured','#Applications','#Leases','#Spend','#Cost / lead','#Cost / lease'],src.map(s=>`<tr>${td(`<button type="button" class="link" data-action="source" data-id="${s.id}"><i class="dot" style="background:${s.color}"></i>${s.name}</button><small>${s.paid?'Paid acquisition':'Cost not allocated'}</small>`)}${td(s.leads,true)}${compact?'':td(s.scheduled,true)+td(s.toured,true)+td(s.applied,true)}${td(s.leases,true)}${td(s.paid?money(s.spend):'—',true)}${compact?'':td(s.paid&&s.leads?money(s.spend/s.leads):'—',true)}${td(s.paid&&s.leases?money(s.spend/s.leases):'—',true)}</tr>`));}
const leadStatus=l=>l.leased?'Lease signed':l.applied?'Applied':l.toured?'Tour completed':l.scheduled?'Tour scheduled':'Enquiry received';
function leadJourneys(m){const list=marketingJourneyRecords(m);leadPage=Math.min(leadPage,Math.max(0,Math.ceil(list.length/10)-1));return `<div class="metrics">${metric('Known original source',pct(m.leads.filter(l=>l.source!=='unknown').length,m.leads.length),`${m.leads.filter(l=>l.source==='unknown').length} records need source review`,'target')}${metric('Unique enquiries',m.leads.length,'One record per sample prospect','people')}${metric('Converted prospects',m.leases,'Signed lease recorded','check')}${metric('Attribution model','Original','Source recorded at first contact','chart')}</div>${panel('Prospect journeys','Open a record to see its milestones and sample follow-up workflow.',`<div class="toolbar"><div class="toolbar-group"><select id="lead-source" aria-label="Original source"><option value="all">All sources</option>${selectedSources(reportFilters()).map(s=>`<option value="${s.id}" ${leadSource===s.id?'selected':''}>${s.name}</option>`).join('')}</select><select id="marketing-stage" aria-label="Leasing milestone">${marketingStages.map(([id,label])=>`<option value="${id}" ${marketingStage===id?'selected':''}>${label}</option>`).join('')}</select><small>${list.length} prospects</small></div><input id="lead-search" aria-label="Search prospects" placeholder="Search prospect or property…" value="${esc(leadSearch)}"></div>${list.length?table(['Prospect','Property','Original source','Created','Furthest milestone',''],list.slice(leadPage*10,leadPage*10+10).map(l=>`<tr>${td(`<button type="button" class="link" data-action="lead" data-id="${l.id}">${l.name}</button><small>${l.id}</small>`)}${td(pName(l.property))}${td(sName(l.source))}${td(l.created)}${td(chip(leadStatus(l),l.leased?'good':l.scheduled?'info':''))}${td(btn('Open','lead',`data-id="${l.id}"`,'secondary small'))}</tr>`)):empty('No prospects found','Try another source or search term.')}${pagination('lead',leadPage,10,list.length)}`,'','full')}`;}
function recommendations(m,src){const paid=src.filter(s=>s.paid&&s.leases),best=[...paid].sort((a,b)=>a.spend/a.leases-b.spend/b.leases)[0];const items=[{key:'reviews-'+filters.property,title:'Close the resident feedback loop',body:`${m.open} reviews are awaiting a response; ${m.overdue} are marked overdue. Assign an owner and work through the response queue.`,label:'Resident experience',tone:'warn',task:'Clear outstanding resident reviews'},{key:'source-'+filters.property,title:'Review the next budget allocation',body:best?`${best.name} delivers a sample paid cost per lease of ${money(best.spend/best.leases)}. Review lead quality, available homes and volume before changing budget.`:'No paid leases are present in this selection. Review the full cohort before making a budget decision.',label:'Marketing efficiency',tone:'info',task:'Review source efficiency and next budget allocation'},{key:'tracking-'+filters.property,title:'Improve source completeness',body:`${m.leads.filter(l=>l.source==='unknown').length} enquiries have an unknown original source. Check forms, tracking parameters and CRM source mapping.`,label:'Data quality',tone:'',task:'Review unknown original-source records'}];return `<div class="insight">${icon('spark')}<span>These transparent, rule-based suggestions use the current sample data. Create a task to assign an owner and track the next step.</span></div><div class="grid three">${items.map(r=>`<article class="recommendation">${chip(r.label,r.tone)}<h3>${r.title}</h3><p>${r.body}</p>${btn(state.tasks.some(t=>t.key===r.key&&t.status!=='Done')?'View existing task':'Create task','task',`data-key="${r.key}" data-property="${filters.property}" data-title="${r.task}"`,'secondary')}</article>`).join('')}</div>`;}

// Shared operations and customer branding.
function actionsView(){return heading('A clear next step. An accountable owner.','Turn dashboard insights into actions your teams can follow.')+`<div class="metrics">${metric('Open actions',state.tasks.filter(t=>t.status!=='Done').length,'Across this demo workspace','tasks')}${metric('In progress',state.tasks.filter(t=>t.status==='In progress').length,'Work picked up by an owner','clock')}${metric('Completed',state.tasks.filter(t=>t.status==='Done').length,'Actions marked done in this browser','check')}${metric('Review responses',Object.keys(state.responses).length,'Completed during this demo','message')}</div>${panel('Team action centre','Update a task’s status or reassign its owner.',state.tasks.length?state.tasks.map(t=>`<div class="task ${t.status==='Done'?'done':''}"><span class="round-icon">${icon(t.status==='Done'?'check':'tasks',13)}</span><div class="task-info"><h3>${esc(t.title)}</h3><small>${pName(t.property)}</small></div><select data-task-owner="${esc(t.id)}" aria-label="Owner for ${esc(t.title)}">${properties.map(p=>`<option ${p.owner===t.owner?'selected':''}>${p.owner}</option>`).join('')}</select><select data-task-status="${esc(t.id)}" aria-label="Status for ${esc(t.title)}">${['Open','In progress','Done'].map(v=>`<option ${v===t.status?'selected':''}>${v}</option>`).join('')}</select></div>`).join(''):empty('Your action centre is ready','Create a task from a review, a source recommendation or a survey follow-up.',btn('Explore recommendations','navigate','data-route="attribution/recommendations"')),'','full')}${state.activity.length?panel('Recent demo activity','Changes made in this browser.',state.activity.slice(0,8).map(a=>`<div class="row"><div><strong>${esc(a.text)}</strong><small>${esc(a.kind)} · ${new Date(a.time).toLocaleTimeString('en-CA',{hour:'2-digit',minute:'2-digit'})}</small></div>${icon('check')}</div>`).join('')):''}`;}
function connectionsView(){return heading('One workspace. A connected vision.','The prototype uses sample data. Live connections are a separate implementation phase.')+`<div class="insight">${icon('info')}<span>Connection cards describe the intended data flow. No credentials are collected and no vendor accounts are connected in this version.</span></div><div class="connection-grid">${[['Birdeye','Reputation & resident feedback','Reviews, response status, listings and resident feedback.','star'],['Hyly / Halo','Lead attribution','Original sources, prospect milestones and conversion performance.','chart'],['Property management system','Yardi / Entrata / MRI','Property identifiers, occupancy and lease outcomes.','building'],['Google Ads','Paid acquisition','Campaign spend, impressions, clicks and source mapping.','target'],['Google Analytics','Website performance','Sessions, engagement and website conversion events.','globe'],['Meta','Social & advertising','Campaign delivery, engagement and attributed enquiries.','people']].map(([name,scope,desc,symbol])=>`<article class="connection"><div class="connection-icon">${icon(symbol,23)}</div><h3>${name}</h3><p>${scope}</p>${chip('Demo data only')}<p>${desc}</p>${btn('View connection plan','connection',`data-name="${name}" data-scope="${scope}"`,'secondary small')}</article>`).join('')}</div>`;}
