// Dialogs preserve context and keep all actions explicitly within the demo.
function openDialog(title,sub,body){lastFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-header"><div><h2 id="dialog-title">${title}</h2><p>${sub}</p></div><button type="button" class="close" data-action="close" aria-label="Close dialog">${icon('close',15)}</button></div>${body}`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close')?.focus();}
function closeDialog(){if(dialog.open)dialog.close();}
dialog.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
function propertyWebsiteMarkup(p) {
  const website = p.website && new URL(p.website, location.origin);
  const websiteLink = website && (website.protocol === 'https:' || (p.demoWebsite && website.origin === location.origin));
  const directions = p.address && new URL('https://www.google.com/maps/dir/?' + new URLSearchParams({api:'1',destination:p.demoWebsite ? p.city + ', ON' : p.address}));
  const phone = p.phone && p.phone.replace(/[^\d+]/g,'');
  return `<section class="property-section" aria-labelledby="property-contact-title">
    <div class="property-section-heading"><h3 id="property-contact-title">Property information</h3>${p.demoWebsite ? chip('Sample property') : ''}</div>
    <div class="property-contact">
      <div><small>Location</small><strong>${esc(p.address || p.city)}${p.demoWebsite ? ' (sample)' : ''}</strong></div>
      <div><small>Leasing phone</small>${phone ? `<a href="tel:${esc(phone)}">${esc(p.phone)}</a>` : '<span>Unavailable</span>'}</div>
    </div>
    <div class="property-links">
      ${websiteLink ? `<a class="btn secondary" href="${esc(website.href)}" target="_blank" rel="noopener noreferrer">${icon('globe',15)} ${p.demoWebsite ? 'Sample property website' : 'Property website'}</a>` : ''}
      ${directions ? `<a class="btn secondary" href="${esc(directions.href)}" target="_blank" rel="noopener noreferrer">${icon('target',15)} ${p.demoWebsite ? 'Google Maps · City directions' : 'Google Maps directions'}</a>` : ''}
    </div>
  </section>
  <section class="property-section" aria-labelledby="property-website-title">
    <div class="property-section-heading"><h3 id="property-website-title">From the property website</h3></div>
    <div data-listing-content role="status">${websiteLink ? 'Loading website highlights…' : 'Property website unavailable.'}</div>
  </section>`;
}

async function loadPropertyWebsite(p, container) {
  if (!p.website) return;
  try {
    const response = await fetch('/api/property-website/' + encodeURIComponent(p.id), {signal:AbortSignal.timeout(10000)});
    if (!response.ok) throw new Error('Website unavailable');
    const {images, amenities, suites} = await response.json();
    if (!container.isConnected || !dialog.open) return;
    container.removeAttribute('role');
    const features = (title, items) => items.length
      ? `<div><h4>${title}</h4><ul>${items.map(item => `<li>${esc(item)}</li>`).join('')}</ul></div>` : '';
    container.innerHTML = `
      ${p.demoWebsite ? '<p class="small">Sample listing content and illustrative photos.</p>' : ''}
      <div data-property-gallery></div>
      ${amenities.length || suites.length ? `<div class="property-features">${features('Community amenities', amenities)}${features('Suite features', suites)}</div>` : ''}
      ${images.length || amenities.length || suites.length ? '' : '<p class="small">No gallery or highlights found on this listing.</p>'}`;
    if (images.length) propertyGallery(container.querySelector('[data-property-gallery]'), images);
  } catch {
    container.textContent = 'Website highlights are temporarily unavailable.';
  }
}

function propertyGallery(container, images) {
  let index = 0;
  container.innerHTML = `<div class="property-gallery" role="region" aria-label="Property photos" aria-roledescription="carousel">
    <div class="property-photo"><img referrerpolicy="no-referrer"><span hidden>Photo unavailable</span></div>
    <div class="gallery-controls">
      <button class="btn secondary" type="button" aria-label="Previous photo">‹</button>
      <span class="small" aria-live="polite"></span>
      <button class="btn secondary" type="button" aria-label="Next photo">›</button>
    </div>
  </div>`;
  const image = container.querySelector('img');
  const status = container.querySelector('.gallery-controls span');
  const [previous,next] = container.querySelectorAll('button');
  function showPhoto() {
    const {url, alt} = images[index];
    image.hidden = false;
    image.nextElementSibling.hidden = true;
    image.alt = alt || 'Property photo ' + (index + 1);
    image.src = url;
    status.textContent = `${index + 1} / ${images.length}${alt ? ' · ' + alt : ''}`;
  }
  function move(step) {
    index = (index + images.length + step) % images.length;
    showPhoto();
  }
  image.addEventListener('error', () => {
    image.hidden = true;
    image.nextElementSibling.hidden = false;
  });
  previous.hidden = next.hidden = images.length === 1;
  previous.addEventListener('click', () => move(-1));
  next.addEventListener('click', () => move(1));
  container.addEventListener('keydown', event => {
    if (images.length < 2 || !['ArrowLeft','ArrowRight'].includes(event.key)) return;
    event.preventDefault();
    move(event.key === 'ArrowLeft' ? -1 : 1);
  });
  showPhoto();
}

function propertyDialog(id){const p=properties.find(p=>p.id===id);if(!p)return;const m=metrics({...reportFilters(),property:id,pmc:'all',city:'all'},state);openDialog(p.name,`${p.code} · ${p.city} · ${p.type}`,`${route().module==='attribution'?funnel(m).replaceAll('data-action="marketing-stage"',`data-action="marketing-stage" data-property="${p.id}"`):leasing.stageCards(m,p.id)}<div class="dialog-metrics"><div><small>Occupancy</small><strong>${pct(p.occupied,p.homes)}</strong><small>${p.occupied} / ${p.homes} homes</small></div><div><small>Leases signed</small><strong>${m.leases}</strong><small>${m.leads.length} enquiries</small></div><div><small>Review rating</small><strong>${m.rating.toFixed(2)}</strong><small>${m.open} open reviews</small></div></div>${propertyWebsiteMarkup(p)}<div class="detail-grid"><div><small>Management company</small><strong>${p.pmc}</strong></div><div><small>Property owner</small><strong>${p.owner}</strong></div><div><small>Advertising spend</small><strong>${money(m.spend)}</strong></div><div><small>Lead-to-lease</small><strong>${pct(m.leases,m.leads.length)}</strong></div></div><div class="insight">${icon('spark')}<span>${m.overdue?`${m.overdue} reviews need a response. Review resident concerns alongside acquisition performance.`:'The response queue is within the sample service window. Review source efficiency for the next budget discussion.'}</span></div><div class="dialog-actions">${btn('View marketing intelligence','scope',`data-id="${p.id}" data-route="attribution"`,'secondary')}${btn('Open reputation workspace','scope',`data-id="${p.id}" data-route="reputation"`)}</div>`);loadPropertyWebsite(p,dialog.querySelector("[data-listing-content]"));}
function getReview(id){const r=reviews.find(r=>r.id===id);return r?{...r,answered:r.answered||Boolean(state.responses[id]),response:state.responses[id],owner:state.assignments[id]||r.owner}:null;}
function reviewDialog(id){const r=getReview(id);if(!r)return;const response=r.response||'Thank you for sharing your experience. Our property team appreciates your feedback and will follow up on the points you raised.';openDialog('Review & response',`${pName(r.property)} · ${r.platform} · ${r.date}`,`<div class="review-person"><span class="avatar">${r.name[0]}</span><div><strong>${r.name}</strong><div>${stars(r.rating)}</div></div>${chip(r.answered?'Responded':r.overdue?'Overdue':'Awaiting response',r.answered?'good':'warn')}</div><blockquote class="quote">${r.text}</blockquote><div class="field"><label for="review-owner">Assigned owner</label><select id="review-owner" data-review-owner="${r.id}">${properties.map(p=>`<option ${p.owner===r.owner?'selected':''}>${p.owner}</option>`).join('')}</select></div>${r.answered?`<h3>Saved response</h3><blockquote class="quote">${esc(response)}</blockquote>`:`<form id="review-form" data-id="${r.id}"><div class="field"><label for="review-response">Response draft</label><textarea id="review-response" name="response" maxlength="3000" required placeholder="Write a thoughtful response to this resident…"></textarea></div><p id="form-error" role="alert" style="font-size:12px;color:var(--red)"></p><div class="notice">Demo response only. Completing this action updates the dashboard; nothing is posted to Google, Birdeye or another service.</div><div class="dialog-actions">${btn(icon('spark',14)+' Use sample draft','draft',`data-id="${r.id}"`,'secondary')}<button type="submit" class="btn">Complete demo response</button></div></form>`}<div class="divider"></div><h3>Does this need a team follow-up?</h3><p class="small" style="margin:7px 0 13px">Create an internal demo task linked to this review.</p>${btn('Create follow-up task','task',`data-key="review-${r.id}" data-property="${r.property}" data-title="Follow up on ${r.topic.toLowerCase()} feedback at ${pName(r.property)}"`,'secondary small')}`);}
function leadDialog(id){leasing.open(id);}
function listingDialog(id){const p=properties.find(p=>p.id===id);if(!p)return;const field=id==='north'?'Office hours':'Phone number',listed=id==='north'?'Monday–Friday, 9 am–5 pm':'416-555-0119',correct=id==='north'?'Monday–Saturday, 9 am–6 pm':'416-555-0128';openDialog('Resolve listing discrepancy',p.name+' · Google Business Profile',`<div class="detail-grid"><div><small>Field</small><strong>${field}</strong></div><div><small>Status</small><strong class="warning">Needs attention</strong></div><div><small>Listed value</small><strong>${listed}</strong></div><div><small>Property master value</small><strong>${correct}</strong></div></div><div class="notice">This is a sample correction. No external listing is changed.</div><div class="dialog-actions">${btn('Mark sample listing resolved','resolve-listing',`data-id="${id}"`)}</div>`);}
function connectionDialog(name,scope){openDialog(esc(name)+' connection plan',esc(scope),`<div class="insight">${icon('plug')}<span>Currently powered by fictional demo records.</span></div><div class="definition-list"><h3>1. Confirm access</h3><p>Confirm the vendor’s available endpoints, account access, commercial terms and permitted branding for the intended deployment.</p><h3>2. Map the records</h3><p>Match properties and prospect identifiers, define the source of truth and agree on metric definitions.</p><h3>3. Pilot the connection</h3><p>Build a server-side connector, validate a small property sample and reconcile records before expanding access.</p></div><div class="dialog-actions">${btn('Create integration planning task','task',`data-key="integration-${esc(name)}" data-property="all" data-title="Confirm ${esc(name)} integration access and data mapping"`)}</div>`);}
function definitions(){openDialog('How the numbers are calculated','A shared vocabulary for the CEO demo.',`<div class="definition-list"><h3>Reporting cohort</h3><p>Enquiries created in the selected month. Cumulative prospect milestones are recorded through November 13, 2026. Demo tour bookings can update the sample schedule count.</p><h3>Lead-to-lease conversion</h3><p>Leases signed ÷ unique enquiries in that creation cohort. Every signed lease has an application, completed tour and scheduled tour in the sample data.</p><h3>Paid cost per lease vs blended ad spend per lease</h3><p>Paid cost per lease uses leases from Google Ads, ILS and Meta. Blended ad spend per lease uses all leases. Organic and referral acquisition costs are unallocated, not zero.</p><h3>Original-source attribution</h3><p>One source recorded at first enquiry receives the lease credit. This demo does not implement multi-touch credit or identity resolution across live systems.</p><h3>Leasing velocity</h3><p>P75 is the nearest-rank 75th percentile of enquiry-to-lease days among converted prospects. Unconverted prospects are excluded.</p><h3>Review rating and response rate</h3><p>Rating is the mean star rating across reviews received in the selected period. Response rate is answered reviews ÷ all reviews. Overdue flags are part of the fictional snapshot.</p><h3>Resident NPS</h3><p>A separate survey: percentage of promoters (9–10) minus detractors (0–6). Review stars are never treated as NPS.</p><h3>Snapshot and illustrative views</h3><p>Occupancy, listing health, competitor ratings and survey results use fixed fictional snapshots. Website and social analytics are illustrative period data. All resident comments and prospect names are fictional.</p></div>`);}
function guidedDemo(){openDialog('Your five-minute MF Hub demo','A clear story: see the issue, inspect the evidence, take action.',`<div class="tour-step"><span class="round-icon">1</span><div><h3>Start with the portfolio</h3><p>Compare occupancy, acquisition cost and resident experience across four properties.</p>${btn('Open portfolio','navigate','data-route="portfolio"','secondary small')}</div></div><div class="tour-step"><span class="round-icon">2</span><div><h3>Close the resident feedback loop</h3><p>Open an overdue review, prepare a response and complete it. Watch the open count decrease.</p>${btn('Open review inbox','navigate','data-route="reputation/inbox"','secondary small')}</div></div><div class="tour-step"><span class="round-icon">3</span><div><h3>Connect marketing spend to leases</h3><p>Compare sources, open a prospect journey and create a follow-up or budget-review task.</p>${btn('Compare sources','navigate','data-route="attribution/sources"','secondary small')}</div></div><div class="tour-step"><span class="round-icon">4</span><div><h3>Show the customer’s own identity</h3><p>Change the portfolio name and accent colour, then revisit the dashboards.</p>${btn('Open brand settings','navigate','data-route="settings"','secondary small')}</div></div>`);}
function searchDialog(){openDialog('Search your portfolio','Properties and sample prospects in the selected reporting month.',`<div class="field"><label for="global-search">Search</label><input id="global-search" placeholder="Try Northpoint or Alex…" autocomplete="off"></div><div id="search-results" class="results"></div>`);searchResults('');document.getElementById('global-search').focus();}
function searchResults(query){const q=query.trim().toLowerCase(),ps=properties.filter(p=>`${p.name} ${p.city} ${p.pmc}`.toLowerCase().includes(q)),ls=q?leads.filter(l=>l.month===Number(filters.month)&&`${l.name} ${l.id} ${pName(l.property)}`.toLowerCase().includes(q)).slice(0,8):[];const output=ps.map(p=>`<button type="button" class="search-result" data-action="property" data-id="${p.id}">${icon('building')}<span><strong>${p.name}</strong><small>${p.city} · ${p.pmc}</small></span></button>`).join('')+ls.map(l=>`<button type="button" class="search-result" data-action="lead" data-id="${l.id}">${icon('people')}<span><strong>${l.name}</strong><small>${pName(l.property)} · ${l.id}</small></span></button>`).join('');document.getElementById('search-results').innerHTML=output||empty('No matching records','Try a property or prospect name.');}
function exportData(){const {module,tab}=route(),scope=reportFilters(),m=metrics(scope,state);if(module==='pipeline'||module==='communications'){leasing.exportList(module==='pipeline'&&tab!=='overview'?tab:'all');return;}let rows,file;
 if(module==='call-center'){file='call-center';rows=callCenter.exportRows(tab);}
 else if(module==='reputation'){file='reputation';rows=[['Review ID','Property','Date','Stars','Source','Topic','Response status','Owner'],...m.reviews.map(r=>[r.id,pName(r.property),r.date,r.rating,r.platform,r.topic,r.answered?'Responded':'Open',r.owner])];}
 else if(module==='attribution'&&tab==='journeys'){file='lead-journeys';rows=[['Lead ID','Name','Property','Original source','Created','Stage','Lease date','Days to lease'],...marketingJourneyRecords(m).map(l=>[l.id,l.name,pName(l.property),sName(l.source),l.created,leadStatus(l),l.leaseDate,l.days])];}
 else if(module==='attribution'){file='marketing-intelligence';rows=[['Source','Marketing channel','Enquiries','Scheduled','Toured','Applications','Leases','Ad spend CAD','Paid cost per lease CAD','Cohort start','Cohort end','Spend basis'],...sourceMetrics(scope,state).map(s=>[s.name,s.channel,s.leads,s.scheduled,s.toured,s.applied,s.leases,s.paid?s.spend.toFixed(2):'Unallocated',s.paid&&s.leases?(s.spend/s.leases).toFixed(2):'Unallocated',reportingRange(scope).start,reportingRange(scope).end,marketingFilters.range==='custom'?'Daily prorated estimate':'Monthly sample totals'])];}
 else{file='portfolio';rows=[['Property','City','Homes','Occupied','Enquiries','Leases','Advertising spend CAD','Review rating','Open reviews'],...m.properties.map(p=>{const a=metrics({...filters,property:p.id},state);return[p.name,p.city,p.homes,p.occupied,a.leads.length,a.leases,a.spend,a.rating.toFixed(2),a.open];})];}
 const blob=new Blob(['\uFEFF'+csv(rows)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`MF-Hub-${file}-${reportingRange(scope).start}-to-${reportingRange(scope).end}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('CSV exported for your current selection.');}

// Delegated events keep filters and workflows connected after each render.
const callCenter=createCallCenter({esc,icon,btn,chip,panel,heading,filters,getState:()=>state,render});
const leasing=createLeasingWorkspace({esc,btn,chip,heading,panel,metric,icon,money,pName,sName,filters,getState:()=>state,render,navigate,persist,toast});
async function onAction(e){const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;
 try{
  if(callCenter.action(b)||leasing.action(b))return;
  if(action==='marketing-reset'){resetMarketingFilters();render();}
  else if(action==='marketing-stage'){if(b.dataset.property)Object.assign(filters,{property:b.dataset.property,pmc:'all',city:'all'});marketingStage=b.dataset.stage;leadSource='all';leadSearch='';leadPage=0;navigate('attribution/journeys');}
  else if(action==='navigate')navigate(b.dataset.route);
  else if(action==='close')closeDialog();
  else if(action==='menu'){mobileOpen=!mobileOpen;render();}else if(action==='close-menu'){mobileOpen=false;render();}
  else if(action==='clear'){Object.assign(filters,{property:'all',city:'all',pmc:'all'});render();}
  else if(action==='export')exportData();
  else if(action==='property')propertyDialog(id);
  else if(action==='scope'){Object.assign(filters,{property:id,pmc:'all',city:'all'});inboxPage=leadPage=0;navigate(b.dataset.route);}
  else if(action==='review')reviewDialog(id);
  else if(action==='review-page'){inboxPage+=Number(b.dataset.delta);render();}
  else if(action==='lead-page'){leadPage+=Number(b.dataset.delta);render();}
  else if(action==='source'){leadSource=id;marketingStage='all';leadPage=0;leadSearch='';navigate('attribution/journeys');}
  else if(action==='lead')leadDialog(id);
  else if(action==='book-tour'){const changed=bookTour(state,id);persist();render();leadDialog(id);toast(changed?'Sample tour booked. The scheduled-tour count increased by one.':'This prospect already has a scheduled tour.');}
  else if(action==='draft'){const r=getReview(id);document.getElementById('review-response').value=r.rating<=3?`Hi ${r.name.split(' ')[0]}, thank you for sharing this feedback. I’m sorry that your experience at ${pName(r.property)} fell short. Our property team would like to understand your ${r.topic.toLowerCase()} concern and agree on a clear next step. Please contact the leasing office directly so we can follow up privately.`:`Hi ${r.name.split(' ')[0]}, thank you for taking the time to share your experience at ${pName(r.property)}. We’re glad to hear your feedback and will pass your kind words to the team. We appreciate having you in our community.`;document.getElementById('review-response').focus();}
  else if(action==='task'){createTask(state,{title:b.dataset.title,property:b.dataset.property,key:b.dataset.key,owner:properties.find(p=>p.id===b.dataset.property)?.owner||properties[0].owner});persist();navigate('actions');toast('Demo task ready. You can change its owner and status.');}
  else if(action==='listing')listingDialog(id);
  else if(action==='resolve-listing'){if(!state.listingFixes.includes(id))state.listingFixes.push(id);persist();closeDialog();render();toast('Sample listing resolved. Listing health updated.');}
  else if(action==='connection')connectionDialog(b.dataset.name,b.dataset.scope);
  else if(action==='accent'){const draftName=document.getElementById('brand-name')?.value;state.accent=id;persist();render();if(draftName!==undefined)document.getElementById('brand-name').value=draftName;}
  else if(action==='reset-dialog')openDialog('Reset this demo?','Restore the original sample workspace.',`<p class="muted" style="font-size:12px;line-height:1.8">This removes saved responses, tasks, assignments, bookings and branding in this browser. No external data is affected.</p><div class="dialog-actions">${btn('Keep my changes','close','','secondary')}${btn('Reset demo','reset','','danger')}</div>`);
  else if(action==='reset'){resetMarketingFilters();state=prepareCRM(defaultState());persist();Object.assign(filters,{property:'all',pmc:'all',city:'all',month:10});inboxStatus='open';inboxRating='all';inboxSearch='';leadSearch='';leadSource='all';inboxPage=leadPage=0;navigate('portfolio');toast('Demo reset. Ready for your next presentation.');}
  else if(action==='demo')guidedDemo();
  else if(action==='definitions')definitions();
  else if(action==='search')searchDialog();
 }catch(error){toast(error.message||'This demo action could not be completed.');}
}
root.addEventListener('click',onAction);dialog.addEventListener('click',onAction);
root.addEventListener('change',e=>{const el=e.target;if(leasing.change(el))return;
 if(el.dataset.marketing){const key=el.dataset.marketing;
  if(key==='range'){
   if(el.value==='9'||el.value==='10'){filters.month=Number(el.value);marketingFilters.range='month';}
   else if(el.value==='all')Object.assign(marketingFilters,{range:'all',dateFrom:'2026-09-01',dateTo:'2026-10-31'});
   else{const {start,end}=reportingRange(reportFilters());Object.assign(marketingFilters,{range:'custom',dateFrom:start,dateTo:end});}
  }else{marketingFilters[key]=el.value;if(key==='channel'||key==='acquisition'){
   if(!selectedSources({...marketingFilters,source:'all'}).some(s=>s.id===marketingFilters.source))marketingFilters.source='all';
  }}
  leadSource='all';leadPage=0;render();document.getElementById(el.id)?.focus();return;
 }
 if(el.id==='marketing-stage'){marketingStage=el.value;leadPage=0;render();return;}
if(el.dataset.filter){callCenter.resetPage();filters[el.dataset.filter]=el.dataset.filter==='month'?Number(el.value):el.value;inboxPage=leadPage=0;render();}else if(el.id==='inbox-status'){inboxStatus=el.value;inboxPage=0;render();}else if(el.id==='inbox-rating'){inboxRating=el.value;inboxPage=0;render();}else if(el.id==='lead-source'){leadSource=el.value;leadPage=0;render();}else if(el.dataset.taskOwner||el.dataset.taskStatus){const task=state.tasks.find(t=>t.id===(el.dataset.taskOwner||el.dataset.taskStatus));if(task){if(el.dataset.taskOwner)task.owner=el.value;else task.status=el.value;persist();render();toast('Task updated.');}}});
root.addEventListener('input',e=>{const el=e.target;if(leasing.input(el))return;if(el.id==='brand-name')el.setCustomValidity('');if(el.id==='review-search'||el.id==='lead-search'){const id=el.id,value=el.value,pos=el.selectionStart;if(id==='review-search'){inboxSearch=value;inboxPage=0;}else{leadSearch=value;leadPage=0;}render();const input=document.getElementById(id);input.focus();input.setSelectionRange(pos,pos);}});
dialog.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value);});
dialog.addEventListener('change',e=>{if(e.target.dataset.reviewOwner){state.assignments[e.target.dataset.reviewOwner]=e.target.value;persist();render();}});
root.addEventListener('submit',e=>{if(leasing.submit(e))return;
 if(e.target.id==='marketing-dates'){e.preventDefault();const data=new FormData(e.target),dates={dateFrom:data.get('dateFrom'),dateTo:data.get('dateTo')};try{reportingRange(dates);Object.assign(marketingFilters,dates);leadPage=0;render();document.getElementById('marketing-from')?.focus();}catch(error){document.getElementById('marketing-date-error').textContent=error.message;}return;}
if(e.target.id==='brand-form'){e.preventDefault();const value=new FormData(e.target).get('brand').trim();if(!value){document.getElementById('brand-name').setCustomValidity('Enter a portfolio name.');document.getElementById('brand-name').reportValidity();return;}state.brand=value.slice(0,50);persist();render();toast('Workspace branding updated.');}});
dialog.addEventListener('submit',e=>{if(e.target.id==='review-form'){e.preventDefault();try{respond(state,e.target.dataset.id,new FormData(e.target).get('response'));persist();closeDialog();render();toast('Demo response completed. Reputation metrics updated.');}catch(error){document.getElementById('form-error').textContent=error.message;}}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('main').focus();});
window.addEventListener('hashchange',()=>{closeDialog();render();});
render();
